structure.mermaidSource:
flowchart TD
  start["Localizar Verbo em -ria ou Subjuntivo"] --> dec_cenario{"Qual o cenário do entorno textual?"}
  dec_cenario -- "Projetos, Teorias ou Modais de Potencialidade" --> dec_potencial{"Banca classifica como Hipótese/Possibilidade?"}
  dec_potencial -- "Sim" --> res_potencial_certo["Item CERTO (Nuance de Hipótese/Possibilidade)"]
  dec_potencial -- "Não (Alega Impossibilidade/Fato Improvável)" --> res_potencial_errado["Item ERRADO (Extrapolação Incorreta)"]
  dec_cenario -- "Citação de Terceiros em Discurso Atribuído" --> proc_regra_depois["Aplicar Regra: O Que Vem Depois Salva (Ler período seguinte)"]
  proc_regra_depois --> dec_oposicao{"Período seguinte traz afirmação categórica em sentido oposto?"}
  dec_oposicao -- "Sim" --> res_duvida_certo["Item CERTO (Marca de Tese Duvidosa/Incerta)"]
  dec_oposicao -- "Não" --> res_duvida_errado["Item ERRADO (Dúvida Não Confirmada)"]
  dec_cenario -- "Banca alega nuance de Impossibilidade" --> dec_impedimento{"Texto registra condição adversativa categórica que inviabilizou o fato?"}
  dec_impedimento -- "Sim" --> res_impossivel_certo["Item CERTO (Nuance de Impossibilidade Real)"]
  dec_impedimento -- "Não" --> res_impossivel_errado["Item ERRADO (Apenas Hipótese, Não Impossibilidade)"]

flowchart TD
  start["Início: Análise da Tríade de Reescritura"] --> dec_gram{"Há erro de concordância, regência ou flexão?"}
  dec_gram -- "Sim" --> res_erro_gram["Item Incorreto: Violação da Correção Gramatical"]
  dec_gram -- "Não" --> dec_comando{"Qual o foco do comando da questão?"}
  dec_comando -- "Sentido Original" --> dec_sentido{"Houve alteração aspectual, modal ou semântica?"}
  dec_comando -- "Apenas Coerência" --> dec_coerencia{"O texto mantém nexo lógico na argumentação?"}
  dec_sentido -- "Sim" --> res_sentido_mudou["Item Incorreto: Sentido original alterado"]
  dec_sentido -- "Não" --> res_sentido_ok["Item Correto: Correção e Sentido preservados"]
  dec_coerencia -- "Sim" --> res_coerencia_ok["Item Correto: Coerência preservada"]
  dec_coerencia -- "Não" --> res_coerencia_erro["Item Incorreto: Ruptura da coerência textual"]
